INSERT INTO questions
(topic_id, subtopic, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty, source)
VALUES
(1,'Programming Basics','Which keyword declares a block-scoped variable in modern JavaScript?','var','let','define','static','B','The let keyword declares a block-scoped variable.','EASY','Curated placement practice'),
(1,'Object Oriented Programming','What is the main purpose of encapsulation?','To expose all data','To bundle data and methods while controlling access','To create multiple inheritance','To sort objects','B','Encapsulation combines data with related methods and restricts direct access where appropriate.','MEDIUM','Curated placement practice'),
(1,'Programming Concepts','What is the output of a recursive function that has no reachable base case?','It always returns zero','It runs once','It continues until a stack overflow or resource limit','It sorts the input','C','Without a reachable base case, recursive calls continue until the call stack is exhausted.','HARD','Curated placement practice'),
(2,'Stacks','Which data structure follows Last In, First Out?','Queue','Stack','Heap','Graph','B','A stack removes the most recently inserted element first.','EASY','Curated placement practice'),
(2,'Trees','What is the average search complexity in a balanced binary search tree?','O(1)','O(log n)','O(n)','O(n log n)','B','Each comparison removes roughly half of the remaining tree in a balanced BST.','MEDIUM','Curated placement practice'),
(2,'Graphs','Which traversal finds the shortest path in an unweighted graph?','DFS','BFS','Inorder traversal','Heapify','B','BFS explores vertices level by level, so the first visit gives the shortest edge distance.','HARD','Curated placement practice'),
(3,'Searching','What is the time complexity of binary search on a sorted array?','O(n)','O(log n)','O(n log n)','O(1)','B','Binary search halves the search range after each comparison.','EASY','Curated placement practice'),
(3,'Sorting','Which sorting algorithm has O(n log n) average time and is usually in-place?','Bubble sort','Quick sort','Linear search','Counting sort','B','Quicksort has O(n log n) average time and can partition in-place.','MEDIUM','Curated placement practice'),
(3,'Dynamic Programming','What is the key idea behind dynamic programming?','Always choose the largest value','Store results of overlapping subproblems','Use only recursion','Avoid all arrays','B','Dynamic programming stores subproblem results to avoid recomputing overlapping work.','HARD','Curated placement practice'),
(4,'Quantitative Aptitude','What is 20% of 150?','20','25','30','35','C','20% of 150 is 0.20 × 150 = 30.','EASY','Curated placement practice'),
(4,'Probability','A fair coin is tossed twice. What is the probability of getting two heads?','1/2','1/3','1/4','3/4','C','The outcomes are HH, HT, TH, TT, and only one has two heads.','MEDIUM','Curated placement practice'),
(4,'Work and Time','A can complete a task in 12 days and B in 18 days. How long do they take together?','6 days','7.2 days','8 days','9 days','B','Their combined rate is 1/12 + 1/18 = 5/36, so time is 36/5 = 7.2 days.','HARD','Curated placement practice'),
(5,'SQL','Which SQL clause filters rows before grouping?','HAVING','WHERE','ORDER BY','LIMIT','B','WHERE filters individual rows before GROUP BY is applied.','EASY','Curated placement practice'),
(5,'Normalization','What is the main goal of database normalization?','Increase duplicate data','Reduce redundancy and update anomalies','Remove all indexes','Store only numbers','B','Normalization organizes data to reduce duplication and anomalies.','MEDIUM','Curated placement practice'),
(5,'Transactions','Which ACID property ensures a transaction is all-or-nothing?','Consistency','Isolation','Durability','Atomicity','D','Atomicity means every operation in the transaction succeeds or none is applied.','HARD','Curated placement practice'),
(6,'Processes','Which component manages process scheduling in an operating system?','Compiler','Kernel','Loader only','Text editor','B','The kernel manages processes, scheduling, memory and hardware resources.','EASY','Curated placement practice'),
(6,'Memory Management','What does virtual memory allow a system to do?','Disable RAM','Use disk space to extend the apparent memory available to processes','Remove the CPU','Prevent all page faults','B','Virtual memory uses secondary storage to provide processes with a larger logical address space.','MEDIUM','Curated placement practice'),
(6,'Deadlocks','Which condition is required for a deadlock to occur?','Circular wait','Unlimited memory','No processes','Read-only files','A','Circular wait is one of the necessary Coffman conditions for deadlock.','HARD','Curated placement practice'),
(7,'Networking Basics','Which protocol translates domain names into IP addresses?','HTTP','DNS','FTP','SSH','B','DNS resolves human-readable domain names to IP addresses.','EASY','Curated placement practice'),
(7,'Transport Layer','Which protocol provides reliable, ordered delivery?','UDP','IP','TCP','ARP','C','TCP provides connection-oriented, reliable and ordered delivery.','MEDIUM','Curated placement practice'),
(7,'Network Security','What is the primary purpose of a TLS certificate?','Compress files','Authenticate a server and help establish encrypted communication','Increase CPU speed','Replace DNS','B','A TLS certificate helps authenticate the server and supports encrypted HTTPS communication.','HARD','Curated placement practice');
INSERT INTO questions
(topic_id, subtopic, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty, source)
VALUES
(1,'Programming Basics','Which data type stores true or false values?','String','Boolean','Integer','Object','B','A Boolean represents one of two logical values: true or false.','EASY','Curated placement practice'),
(1,'Functions','What does a function parameter represent?','A value supplied to the function','The function name','A compiler error','A database table','A','A parameter is an input variable that receives a value when the function is called.','MEDIUM','Curated placement practice'),
(1,'Recursion','What is the time complexity of naive recursive Fibonacci?','O(1)','O(log n)','O(n)','O(2^n)','D','The naive recursion repeats the same subproblems and grows exponentially.','HARD','Curated placement practice'),
(2,'Arrays','What is the index of the first element in a zero-based array?','0','1','-1','The array length','A','Zero-based indexing starts the first element at index 0.','EASY','Curated placement practice'),
(2,'Linked Lists','Which operation is O(1) at the head of a linked list?','Random access','Insert at head','Binary search','Sort the list','B','A new node can be linked before the current head without scanning the list.','MEDIUM','Curated placement practice'),
(2,'Heaps','What is the time complexity of inserting into a binary heap?','O(1) always','O(log n)','O(n)','O(n log n)','B','After insertion, the element may move up at most the height of the heap.','HARD','Curated placement practice'),
(3,'Searching','Which search works without requiring sorted input?','Binary search','Linear search','Interpolation search','Jump search','B','Linear search checks items sequentially and does not require ordering.','EASY','Curated placement practice'),
(3,'Sorting','Which sorting algorithm repeatedly swaps adjacent out-of-order elements?','Merge sort','Bubble sort','Heap sort','Radix sort','B','Bubble sort compares neighboring elements and swaps them when needed.','MEDIUM','Curated placement practice'),
(3,'Graphs','What is the purpose of memoization?','Delete recursion','Cache results of repeated subproblems','Randomize input','Increase duplicate work','B','Memoization stores previously computed results to avoid repeated computation.','HARD','Curated placement practice'),
(4,'Percentages','If a price increases from 100 to 120, what is the percentage increase?','10%','15%','20%','25%','C','The increase is 20 over an original 100, which equals 20%.','EASY','Curated placement practice'),
(4,'Averages','The average of 10, 20 and 30 is:','15','20','25','30','B','The sum is 60 and 60 divided by 3 is 20.','MEDIUM','Curated placement practice'),
(4,'Permutations','How many arrangements are possible for 5 distinct objects?','25','60','100','120','B','The number of arrangements is 5! = 5×4×3×2×1 = 120.','HARD','Curated placement practice'),
(5,'SQL','Which command retrieves rows from a table?','SELECT','INSERT','UPDATE','DELETE','A','SELECT is used to read data from one or more tables.','EASY','Curated placement practice'),
(5,'Joins','Which join returns matching rows from both tables?','CROSS JOIN','INNER JOIN','FULL DELETE','SELF DROP','B','INNER JOIN returns rows where the join condition matches in both tables.','MEDIUM','Curated placement practice'),
(5,'Indexes','What is a common trade-off of adding database indexes?','Reads always become slower','They use storage and can slow writes','They remove primary keys','They prevent queries','B','Indexes improve many reads but require storage and must be updated during writes.','HARD','Curated placement practice'),
(6,'Operating Systems','Which part of a process contains its local variables and call frames?','Stack','Printer','File system','Network card','A','The process stack stores call frames and local variables.','EASY','Curated placement practice'),
(6,'Scheduling','Which scheduling algorithm assigns a fixed time slice to each process?','Round Robin','Depth First Search','First Fit','Two Phase Commit','A','Round Robin cycles through processes using a fixed time quantum.','MEDIUM','Curated placement practice'),
(6,'Virtual Memory','What causes a page fault?','A requested page is not currently in physical memory','The CPU is idle','A file is compressed','A process exits normally','A','A page fault occurs when the required virtual page must be loaded from secondary storage.','HARD','Curated placement practice'),
(7,'Networking Basics','Which device forwards packets between different networks?','Hub','Router','Keyboard','Repeater only','B','A router forwards packets between networks using IP addressing.','EASY','Curated placement practice'),
(7,'Transport Layer','What does UDP sacrifice compared with TCP?','All addressing','Reliability and ordering guarantees','Packet transmission','Port numbers','B','UDP is connectionless and does not guarantee delivery or order.','MEDIUM','Curated placement practice'),
(7,'Network Security','What does a firewall primarily control?','Network traffic based on rules','Screen brightness','Database normalization','Source code formatting','A','A firewall permits or blocks network traffic according to security rules.','HARD','Curated placement practice');
